ResponseBody = (
    ResponseBodyEmpty
    | ResponseBodySession
    | ResponseBodySessions
    | ResponseBodyNode
    | ResponseBodyParam
    | ResponseBodySlot
    | ResponseBodyParams
    | ResponseBodyBindings
    | ResponseBodyTexture
    | ResponseBodyTextures
    | ResponseBodyTree
    | ResponseBodyNodeInfo
    | ResponseBodyStatus
    | ResponseBodyWarnings
    | ResponseBodyPreview
    | ResponseBodySaved
    | ResponseBodyPresence
    | ResponseBodySlots
    | ResponseBodyWelds
    | ResponseBodyUnfilledSlots
    | ResponseBodyEmptied
    | ResponseBodyExtensions
    | ResponseBodyExtension
)

RESPONSE_BODY_VARIANTS: dict[str, type[ResponseBody]] = {
    "empty": ResponseBodyEmpty,
    "session": ResponseBodySession,
    "sessions": ResponseBodySessions,
    "node": ResponseBodyNode,
    "param": ResponseBodyParam,
    "slot": ResponseBodySlot,
    "params": ResponseBodyParams,
    "bindings": ResponseBodyBindings,
    "texture": ResponseBodyTexture,
    "textures": ResponseBodyTextures,
    "tree": ResponseBodyTree,
    "node_info": ResponseBodyNodeInfo,
    "status": ResponseBodyStatus,
    "warnings": ResponseBodyWarnings,
    "preview": ResponseBodyPreview,
    "saved": ResponseBodySaved,
    "presence": ResponseBodyPresence,
    "slots": ResponseBodySlots,
    "welds": ResponseBodyWelds,
    "unfilled_slots": ResponseBodyUnfilledSlots,
    "emptied": ResponseBodyEmptied,
    "extensions": ResponseBodyExtensions,
    "extension": ResponseBodyExtension,
}


def parse_response_body(message: Mapping[str, Any]) -> ResponseBody:
    """One JSON object as the ResponseBody it is, by its "result" tag."""
    tag = message.get("result")
    found = RESPONSE_BODY_VARIANTS.get(tag) if isinstance(tag, str) else None
    if found is None:
        raise ValueError(f"no ResponseBody carries the result {tag!r}")
    return _decode_class(found, message)


@dataclass(frozen=True, kw_only=True)
class EventModelChanged:
    """The model changed; `rev` is the session's new revision. Observers
    re-read when their last-seen rev is older.
    """

    TAG_FIELD: ClassVar[str] = "event"
    TAG: ClassVar[str] = "model_changed"

    session: SessionId
    rev: int

    def to_wire(self) -> dict[str, Any]:
        """This value, as one JSON object: its tag, then every field it set."""
        return _wire_fields(self)


@dataclass(frozen=True, kw_only=True)
class EventSessionsChanged:
    """The set of open sessions changed: one was created, opened, imported or
    closed. Carries nothing — an observer that cares re-reads
    [`Command::SessionList`], which is the only answer that is not already
    stale by the time it arrives.
    """

    TAG_FIELD: ClassVar[str] = "event"
    TAG: ClassVar[str] = "sessions_changed"

    def to_wire(self) -> dict[str, Any]:
        """This value, as one JSON object: its tag, then every field it set."""
        return _wire_fields(self)


Event = (
    EventModelChanged
    | EventSessionsChanged
)

EVENT_VARIANTS: dict[str, type[Event]] = {
    "model_changed": EventModelChanged,
    "sessions_changed": EventSessionsChanged,
}


def parse_event(message: Mapping[str, Any]) -> Event:
    """One JSON object as the Event it is, by its "event" tag."""
    tag = message.get("event")
    found = EVENT_VARIANTS.get(tag) if isinstance(tag, str) else None
    if found is None:
        raise ValueError(f"no Event carries the event {tag!r}")
    return _decode_class(found, message)


